def exchange(lst1, lst2):
    has_even_lst1 = any(x % 2 == 0 for x in lst1)
    has_even_lst2 = any(x % 2 == 0 for x in lst2)
    has_odd_lst1 = any(x % 2 == 1 for x in lst1)

    if has_even_lst1:
        return "YES"
    if has_even_lst2 and has_odd_lst1:
        return "YES"

    return "NO"

